-- 90_new_retro_games_prerequisites.sql
-- Adds "Prerequisites: <value>" to the 112 games added in
-- 87_outdoor_games_retro70s_batch2.sql and
-- 88_outdoor_games_retro90s_batch2.sql (which predate the Prerequisites
-- field), bringing them in line with the original 448 games. Same
-- REPLACE()-on-the-"\n\nMaterials:"-anchor approach as
-- 89_outdoor_games_prerequisites.sql, for the same byte-for-byte-safety
-- and idempotency reasons.

UPDATE dbo.PacketQuestions SET prompt = REPLACE(prompt, CHAR(10)+CHAR(10)+N'Materials:', CHAR(10)+CHAR(10)+N'Prerequisites: None — a great first-timer activity'+CHAR(10)+CHAR(10)+N'Materials:') WHERE question_id = 5474 AND prompt NOT LIKE N'%Prerequisites:%';
